const { env } = await import('node:process');
const { existsSync } = await import('node:fs');
const input = env.INPUT_HTML;
const output = env.OUTPUT_PDF;
if (!input) throw new Error('Missing INPUT_HTML env var');
if (!output) throw new Error('Missing OUTPUT_PDF env var');
if (!existsSync(input)) throw new Error('Input HTML file does not exist');
globalThis.inputPath = input;
globalThis.outputPath = output;

const mod = await import('@aspirio/topdf');
const fn = mod.default || mod;
await fn({ input: globalThis.inputPath, output: globalThis.outputPath });
globalThis.pdfPath = globalThis.outputPath;
